"""Frozen service rule authority, durable attempts and exact predecessor restoration."""

SCHEMA_SQL = ("DO $service_pin$ BEGIN IF encode(sha256(convert_to(pg_get_functiondef(to_regprocedure('public.assert_automation_version(uuid,uuid)')),'UTF8')),'hex')<> '121526aad908b2cc927a4eb55412e56840984930912753969364b571980a7eb0' THEN RAISE EXCEPTION 'Installed function drift: assert_automation_version(uuid,uuid)'; END IF; IF encode(sha256(convert_to(pg_get_functiondef(to_regprocedure('public.require_automation_current()')),'UTF8')),'hex')<> 'e286e78113a3844dba805bdc7db3b004b04a879b798272f92a5f642603111090' THEN RAISE EXCEPTION 'Installed function drift: require_automation_current()'; END IF; IF encode(sha256(convert_to(pg_get_functiondef(to_regprocedure('public.assert_automation_occurrence(uuid,uuid)')),'UTF8')),'hex')<> 'e4e16ccff90f00418c8c5abb61aadb46518583b295822fbc9dab114c443061c0' THEN RAISE EXCEPTION 'Installed function drift: assert_automation_occurrence(uuid,uuid)'; END IF; IF encode(sha256(convert_to(pg_get_functiondef(to_regprocedure('public.kernel_scope_failed(uuid)')),'UTF8')),'hex')<> '3e768f9418d3ec7a85e49daa5b4a1d77fef19d40df7ed386fdde4ae34121a112' THEN RAISE EXCEPTION 'Installed function drift: kernel_scope_failed(uuid)'; END IF; END; $service_pin$", '\nCREATE TABLE automation_service_grants (\n\tcategory_id UUID NOT NULL, \n\towner_id UUID NOT NULL, \n\twriter_id UUID NOT NULL, \n\trule_id UUID NOT NULL, \n\tpublished_version_id UUID NOT NULL, \n\treceipt_id UUID NOT NULL, \n\texpires_at TIMESTAMP WITH TIME ZONE, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(tenant_id, category_id) REFERENCES categories (tenant_id, id), \n\tFOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id), \n\tUNIQUE (tenant_id, id), \n\tUNIQUE (tenant_id, published_version_id), \n\tUNIQUE (tenant_id, category_id, owner_id, rule_id, published_version_id, writer_id, id), \n\tUNIQUE (tenant_id, category_id, owner_id, id), \n\tFOREIGN KEY(tenant_id, category_id, owner_id, rule_id, published_version_id) REFERENCES automation_rule_versions (tenant_id, category_id, owner_id, rule_id, id), \n\tFOREIGN KEY(tenant_id, writer_id) REFERENCES principals (tenant_id, id), \n\tFOREIGN KEY(tenant_id, receipt_id) REFERENCES action_receipts (tenant_id, id) DEFERRABLE INITIALLY DEFERRED, \n\tCHECK (owner_id<>writer_id)\n)\n\n', 'CREATE INDEX ix_automation_service_grants_category_id ON automation_service_grants (category_id)', 'CREATE INDEX ix_automation_service_grants_tenant_id ON automation_service_grants (tenant_id)', "\nCREATE TABLE automation_causal_chains (\n\tcategory_id UUID NOT NULL, \n\towner_id UUID NOT NULL, \n\troot_grant_id UUID NOT NULL, \n\tbudget JSONB NOT NULL, \n\tmax_depth INTEGER NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(tenant_id, category_id) REFERENCES categories (tenant_id, id), \n\tFOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id), \n\tUNIQUE (tenant_id, id), \n\tFOREIGN KEY(tenant_id, category_id, owner_id, root_grant_id) REFERENCES automation_service_grants (tenant_id, category_id, owner_id, id), \n\tCHECK (max_depth>=0 AND jsonb_typeof(budget)='object')\n)\n\n", 'CREATE INDEX ix_automation_causal_chains_category_id ON automation_causal_chains (category_id)', 'CREATE INDEX ix_automation_causal_chains_tenant_id ON automation_causal_chains (tenant_id)', "\nCREATE TABLE automation_service_attempts (\n\tcategory_id UUID NOT NULL, \n\towner_id UUID NOT NULL, \n\twriter_id UUID NOT NULL, \n\trule_id UUID NOT NULL, \n\tpublished_version_id UUID NOT NULL, \n\tservice_grant_id UUID NOT NULL, \n\tchain_id UUID NOT NULL, \n\tparent_run_id UUID, \n\tdepth INTEGER NOT NULL, \n\ttrigger_kind VARCHAR(32) NOT NULL, \n\ttrigger_key VARCHAR(200) NOT NULL, \n\torigin JSONB NOT NULL, \n\trequest_digest VARCHAR(64) NOT NULL, \n\tstate VARCHAR(16) NOT NULL, \n\terror_code VARCHAR(80), \n\trun_id UUID, \n\tadmitted_at TIMESTAMP WITH TIME ZONE, \n\tdue_at TIMESTAMP WITH TIME ZONE, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(tenant_id, category_id) REFERENCES categories (tenant_id, id), \n\tFOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id), \n\tUNIQUE (tenant_id, id), \n\tUNIQUE (tenant_id, service_grant_id, trigger_key), \n\tUNIQUE (tenant_id, run_id), \n\tFOREIGN KEY(tenant_id, category_id, owner_id, rule_id, published_version_id, writer_id, service_grant_id) REFERENCES automation_service_grants (tenant_id, category_id, owner_id, rule_id, published_version_id, writer_id, id), \n\tFOREIGN KEY(tenant_id, chain_id) REFERENCES automation_causal_chains (tenant_id, id), \n\tFOREIGN KEY(tenant_id, parent_run_id) REFERENCES agent_runs (tenant_id, id), \n\tFOREIGN KEY(tenant_id, run_id) REFERENCES agent_runs (tenant_id, id) DEFERRABLE INITIALLY DEFERRED, \n\tCHECK (depth>=0 AND length(trigger_key)>0), \n\tCHECK (trigger_kind IN ('schedule','domain_event','relative_milestone')), \n\tCHECK (jsonb_typeof(origin)='object' AND request_digest ~ '^[a-f0-9]{64}$'), \n\tCHECK ((state='queued' AND run_id IS NULL AND admitted_at IS NULL AND error_code IS NULL) OR (state='admitted' AND run_id IS NOT NULL AND admitted_at IS NOT NULL AND error_code IS NULL) OR (state='suppressed' AND run_id IS NULL AND admitted_at IS NULL AND error_code IS NOT NULL AND error_code ~ '^[A-Z][A-Z0-9_]{0,79}$')), \n\tCHECK ((depth=0 AND parent_run_id IS NULL) OR (depth>0 AND parent_run_id IS NOT NULL))\n)\n\n", 'CREATE INDEX ix_automation_service_attempts_category_id ON automation_service_attempts (category_id)', 'CREATE INDEX ix_automation_service_attempts_tenant_id ON automation_service_attempts (tenant_id)', 'CREATE INDEX ix_automation_service_chain ON automation_service_attempts (tenant_id, chain_id, state, run_id)', 'CREATE INDEX ix_automation_service_queue ON automation_service_attempts (tenant_id, state, due_at, id)', "CREATE FUNCTION public.automation_service_identity(t uuid,service_owner uuid,service_writer uuid) RETURNS boolean\nLANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $automation_service$\n\n SELECT t=nullif(current_setting('pdos.tenant_id',true),'')::uuid\n  AND service_owner=public.scope_requester() AND service_writer=public.scope_actor()\n  AND service_owner<>service_writer\n  AND EXISTS(SELECT 1 FROM public.principals h WHERE h.tenant_id=t AND h.id=service_owner AND h.kind='human')\n  AND EXISTS(SELECT 1 FROM public.principals a WHERE a.tenant_id=t AND a.id=service_writer AND a.kind='agent');\n$automation_service$", "CREATE FUNCTION public.automation_service_grant_available(t uuid,target uuid,at_time timestamptz) RETURNS boolean\nLANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $automation_service$\n\n SELECT EXISTS(SELECT 1 FROM public.automation_service_grants g\n  JOIN public.automation_rule_versions v ON v.tenant_id=g.tenant_id AND v.category_id=g.category_id\n   AND v.owner_id=g.owner_id AND v.rule_id=g.rule_id AND v.id=g.published_version_id\n  JOIN public.automation_rule_currents cur ON cur.tenant_id=g.tenant_id AND cur.category_id=g.category_id\n   AND cur.owner_id=g.owner_id AND cur.rule_id=g.rule_id AND cur.published_version_id=g.published_version_id\n  WHERE g.tenant_id=t AND g.id=target AND cur.state='active' AND v.action='activate' AND v.state='active'\n   AND v.receipt_id=g.receipt_id AND v.spec->>'trigger_kind' IN ('schedule','domain_event','relative_milestone')\n   AND public.automation_service_identity(t,g.owner_id,g.writer_id)\n   AND EXISTS(SELECT 1 FROM public.principals h WHERE h.tenant_id=t AND h.id=g.owner_id AND h.active AND h.kind='human')\n   AND EXISTS(SELECT 1 FROM public.principals a WHERE a.tenant_id=t AND a.id=g.writer_id AND a.active AND a.kind='agent')\n   AND (SELECT count(*) FROM public.principals a WHERE a.tenant_id=t AND a.active AND a.kind='agent')=1\n   AND public.category_access(t,g.category_id,false)\n   AND at_time>=g.created_at AND (g.expires_at IS NULL OR at_time<g.expires_at));\n$automation_service$", "CREATE FUNCTION public.assert_automation_service_grant(t uuid,target uuid) RETURNS void\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $automation_service$\n\nDECLARE g public.automation_service_grants; v public.automation_rule_versions; r public.action_receipts; c public.confirmations; gx xid; vx xid; rx xid; cx xid;\nBEGIN\n SELECT * INTO STRICT g FROM public.automation_service_grants WHERE tenant_id=t AND id=target;\n SELECT * INTO STRICT v FROM public.automation_rule_versions WHERE tenant_id=t AND id=g.published_version_id;\n SELECT * INTO STRICT r FROM public.action_receipts WHERE tenant_id=t AND id=g.receipt_id;\n SELECT * INTO STRICT c FROM public.confirmations WHERE tenant_id=t AND id=v.confirmation_id;\n SELECT xmin INTO gx FROM public.automation_service_grants WHERE tenant_id=t AND id=g.id;\n SELECT xmin INTO vx FROM public.automation_rule_versions WHERE tenant_id=t AND id=v.id;\n SELECT xmin INTO rx FROM public.action_receipts WHERE tenant_id=t AND id=r.id;\n SELECT xmin INTO cx FROM public.confirmations WHERE tenant_id=t AND id=c.id;\n PERFORM public.assert_automation_members(t,v.id);\n IF ROW(g.category_id,g.owner_id,g.rule_id,g.receipt_id) IS DISTINCT FROM ROW(v.category_id,v.owner_id,v.rule_id,v.receipt_id)\n  OR v.action<>'activate' OR v.state<>'active' OR v.operation<>'ai.automation.activate'\n  OR NOT COALESCE(v.spec->>'trigger_kind' IN ('schedule','domain_event','relative_milestone'),false)\n  OR g.expires_at IS DISTINCT FROM (v.spec#>>'{trigger_config,expires_at}')::timestamptz\n  OR g.owner_id IS DISTINCT FROM public.scope_actor() OR g.owner_id IS DISTINCT FROM public.scope_requester()\n  OR NOT public.category_access(t,g.category_id,true)\n  OR NOT EXISTS(SELECT 1 FROM public.principals h WHERE h.tenant_id=t AND h.id=g.owner_id AND h.active AND h.kind='human')\n  OR NOT EXISTS(SELECT 1 FROM public.principals a WHERE a.tenant_id=t AND a.id=g.writer_id AND a.active AND a.kind='agent')\n  OR (SELECT count(*) FROM public.principals a WHERE a.tenant_id=t AND a.active AND a.kind='agent')<>1\n  OR ROW(r.category_id,r.actor_id,r.requester_id,r.operation,r.subject_type,r.subject_id,r.subject_revision,r.confirmation_id)\n   IS DISTINCT FROM ROW(g.category_id,g.owner_id,g.owner_id,'ai.automation.activate'::varchar,'automation_rule'::varchar,v.id,v.revision,v.confirmation_id)\n  OR r.run_id IS NOT NULL OR r.agent_run_id IS NOT NULL\n  OR c.consumed IS DISTINCT FROM true OR c.operation<>'ai.automation.activate'\n  OR c.actor_id<>g.owner_id OR c.category_id<>g.category_id OR c.subject_type<>'category' OR c.subject_id<>g.category_id\n  OR c.snapshot IS DISTINCT FROM v.command->'review'\n  OR c.created_at>g.created_at OR g.created_at<v.created_at\n  OR gx IS DISTINCT FROM vx OR gx IS DISTINCT FROM rx OR gx IS DISTINCT FROM cx THEN\n  RAISE EXCEPTION 'Service grant requires actual named T1 activation and unique Pai in one transaction' USING ERRCODE='23514'; END IF;\nEND;\n$automation_service$", "CREATE FUNCTION public.assert_automation_causal_chain(t uuid,target uuid) RETURNS void\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $automation_service$\n\nDECLARE chain public.automation_causal_chains; g public.automation_service_grants; v public.automation_rule_versions; chain_xid xid;\nBEGIN\n SELECT * INTO STRICT chain FROM public.automation_causal_chains WHERE tenant_id=t AND id=target;\n SELECT * INTO STRICT g FROM public.automation_service_grants WHERE tenant_id=t AND id=chain.root_grant_id;\n SELECT * INTO STRICT v FROM public.automation_rule_versions WHERE tenant_id=t AND id=g.published_version_id;\n SELECT xmin INTO chain_xid FROM public.automation_causal_chains WHERE tenant_id=t AND id=chain.id;\n IF ROW(chain.category_id,chain.owner_id) IS DISTINCT FROM ROW(g.category_id,g.owner_id)\n  OR chain.budget IS DISTINCT FROM v.spec->'budget' OR chain.max_depth IS DISTINCT FROM (v.spec->>'max_cascade_depth')::integer\n  OR chain.created_at<g.created_at\n  OR NOT COALESCE(public.automation_service_identity(t,g.owner_id,g.writer_id),false)\n  OR (NOT public.automation_service_grant_available(t,g.id,statement_timestamp()) AND NOT EXISTS(\n   SELECT 1 FROM public.automation_service_attempts diagnostic WHERE diagnostic.tenant_id=t AND diagnostic.chain_id=chain.id\n    AND diagnostic.service_grant_id=g.id AND diagnostic.depth=0 AND diagnostic.origin->>'kind'='lifecycle'\n    AND diagnostic.state='suppressed' AND diagnostic.run_id IS NULL AND diagnostic.admitted_at IS NULL AND diagnostic.xmin=chain_xid)) THEN\n  RAISE EXCEPTION 'Causal chain fixes the actual root grant budget and depth' USING ERRCODE='23514'; END IF;\nEND;\n$automation_service$", "CREATE FUNCTION public.assert_automation_service_attempt(t uuid,target uuid) RETURNS void\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $automation_service$\n\nDECLARE a public.automation_service_attempts; g public.automation_service_grants; v public.automation_rule_versions; chain public.automation_causal_chains; r public.agent_runs; ax xid; rx xid;\nBEGIN\n SELECT * INTO STRICT a FROM public.automation_service_attempts WHERE tenant_id=t AND id=target;\n SELECT * INTO STRICT g FROM public.automation_service_grants WHERE tenant_id=t AND id=a.service_grant_id;\n SELECT * INTO STRICT v FROM public.automation_rule_versions WHERE tenant_id=t AND id=g.published_version_id;\n SELECT * INTO STRICT chain FROM public.automation_causal_chains WHERE tenant_id=t AND id=a.chain_id;\n IF a.state<>'suppressed' AND NOT public.automation_service_grant_available(t,g.id,statement_timestamp()) THEN\n  RAISE EXCEPTION 'Unavailable lifecycle attempt must finish suppressed in its own transaction' USING ERRCODE='23514'; END IF;\n IF ROW(a.category_id,a.owner_id,a.writer_id,a.rule_id,a.published_version_id) IS DISTINCT FROM ROW(g.category_id,g.owner_id,g.writer_id,g.rule_id,g.published_version_id)\n  OR a.trigger_kind IS DISTINCT FROM v.spec->>'trigger_kind' OR (a.state='admitted' AND a.depth>chain.max_depth)\n  OR (a.depth=0 AND chain.root_grant_id IS DISTINCT FROM a.service_grant_id)\n  OR (a.depth>0 AND NOT EXISTS(SELECT 1 FROM public.automation_service_attempts parent_attempt\n    WHERE parent_attempt.tenant_id=t AND parent_attempt.run_id=a.parent_run_id AND parent_attempt.state='admitted'\n     AND parent_attempt.chain_id=a.chain_id AND parent_attempt.depth+1=a.depth))\n  OR a.created_at<g.created_at OR a.created_at<chain.created_at\n  OR (a.parent_run_id IS NOT NULL AND (a.parent_run_id IS NOT DISTINCT FROM a.run_id\n   OR NOT EXISTS(SELECT 1 FROM public.agent_runs parent WHERE parent.tenant_id=t AND parent.id=a.parent_run_id AND parent.created_at<=a.created_at))) THEN\n  RAISE EXCEPTION 'Service attempt requires fixed grant actual parent and causal budget chain' USING ERRCODE='23514'; END IF;\n IF a.state='admitted' THEN\n  SELECT * INTO STRICT r FROM public.agent_runs WHERE tenant_id=t AND id=a.run_id;\n  SELECT xmin INTO ax FROM public.automation_service_attempts WHERE tenant_id=t AND id=a.id;\n  SELECT xmin INTO rx FROM public.agent_runs WHERE tenant_id=t AND id=r.id;\n  IF ROW(r.category_id,r.requester_id,r.writer_id,r.trigger,r.intent_key,r.goal,r.intent_digest,r.validation_budget_id,r.token_limit)\n    IS DISTINCT FROM ROW(a.category_id,a.owner_id,a.writer_id,'automation_service'::varchar,('automation-service:'||a.id)::varchar,v.spec->>'goal',a.request_digest,(v.spec->>'validation_budget_id')::uuid,(v.spec->>'token_limit')::integer)\n   OR r.product_id IS DISTINCT FROM (v.spec->>'product_id')::uuid OR r.proposal_id IS NOT NULL OR r.continued_from_id IS NOT NULL\n   OR a.admitted_at<a.created_at OR a.admitted_at<r.created_at\n   OR (a.due_at IS NOT NULL AND a.admitted_at<a.due_at) OR ax IS DISTINCT FROM rx THEN\n   RAISE EXCEPTION 'Admitted service attempt binds its exact new Run and real admission time' USING ERRCODE='23514'; END IF;\n END IF;\nEND;\n$automation_service$", "CREATE FUNCTION public.protect_automation_service_attempt() RETURNS trigger\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $automation_service$\n\nBEGIN\n IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Service attempt history retained' USING ERRCODE='23514'; END IF;\n IF NOT COALESCE(public.automation_service_identity(NEW.tenant_id,NEW.owner_id,NEW.writer_id),false) THEN\n  RAISE EXCEPTION 'Service attempt belongs to actual Pai actor and named delegator' USING ERRCODE='23514'; END IF;\n IF TG_OP='INSERT' THEN\n  IF NEW.state<>'queued' OR NEW.run_id IS NOT NULL OR NEW.admitted_at IS NOT NULL OR NEW.error_code IS NOT NULL THEN\n   RAISE EXCEPTION 'Service attempt starts queued without invented Run' USING ERRCODE='23514'; END IF;\n ELSIF OLD.state<>'queued' OR NEW.state NOT IN ('admitted','suppressed')\n  OR (to_jsonb(NEW)-ARRAY['state','error_code','run_id','admitted_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','error_code','run_id','admitted_at']) THEN\n  RAISE EXCEPTION 'Service attempt only leaves queued once and retains its original origin' USING ERRCODE='23514';\n END IF;\n IF NEW.state<>'suppressed' AND NEW.origin->>'kind' IS DISTINCT FROM 'lifecycle'\n  AND NOT public.automation_service_grant_available(NEW.tenant_id,NEW.service_grant_id,statement_timestamp()) THEN\n  RAISE EXCEPTION 'New queued or admitted service attempt requires current usable grant' USING ERRCODE='23514'; END IF;\n RETURN NEW;\nEND;\n$automation_service$", "CREATE FUNCTION public.reject_automation_service_mutation() RETURNS trigger\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $automation_service$\nBEGIN RAISE EXCEPTION 'Service grants and causal chains are immutable' USING ERRCODE='23514'; END;\n$automation_service$", 'CREATE FUNCTION public.require_automation_service_grant() RETURNS trigger\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $automation_service$\nBEGIN PERFORM public.assert_automation_service_grant(NEW.tenant_id,NEW.id); RETURN NULL; END;\n$automation_service$', 'CREATE FUNCTION public.require_automation_causal_chain() RETURNS trigger\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $automation_service$\nBEGIN PERFORM public.assert_automation_causal_chain(NEW.tenant_id,NEW.id); RETURN NULL; END;\n$automation_service$', 'CREATE FUNCTION public.require_automation_service_attempt() RETURNS trigger\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $automation_service$\nBEGIN PERFORM public.assert_automation_service_attempt(NEW.tenant_id,NEW.id); RETURN NULL; END;\n$automation_service$', 'REVOKE ALL ON FUNCTION public.automation_service_identity(uuid,uuid,uuid) FROM PUBLIC,pdos_next_app,pdos_agent,pdos_next_auth,pdos_next_dispatch', 'REVOKE ALL ON FUNCTION public.automation_service_grant_available(uuid,uuid,timestamptz) FROM PUBLIC,pdos_next_app,pdos_agent,pdos_next_auth,pdos_next_dispatch', 'REVOKE ALL ON FUNCTION public.assert_automation_service_grant(uuid,uuid) FROM PUBLIC,pdos_next_app,pdos_agent,pdos_next_auth,pdos_next_dispatch', 'REVOKE ALL ON FUNCTION public.assert_automation_causal_chain(uuid,uuid) FROM PUBLIC,pdos_next_app,pdos_agent,pdos_next_auth,pdos_next_dispatch', 'REVOKE ALL ON FUNCTION public.assert_automation_service_attempt(uuid,uuid) FROM PUBLIC,pdos_next_app,pdos_agent,pdos_next_auth,pdos_next_dispatch', 'REVOKE ALL ON FUNCTION public.protect_automation_service_attempt() FROM PUBLIC,pdos_next_app,pdos_agent,pdos_next_auth,pdos_next_dispatch', 'REVOKE ALL ON FUNCTION public.reject_automation_service_mutation() FROM PUBLIC,pdos_next_app,pdos_agent,pdos_next_auth,pdos_next_dispatch', 'REVOKE ALL ON FUNCTION public.require_automation_service_grant() FROM PUBLIC,pdos_next_app,pdos_agent,pdos_next_auth,pdos_next_dispatch', 'REVOKE ALL ON FUNCTION public.require_automation_causal_chain() FROM PUBLIC,pdos_next_app,pdos_agent,pdos_next_auth,pdos_next_dispatch', 'REVOKE ALL ON FUNCTION public.require_automation_service_attempt() FROM PUBLIC,pdos_next_app,pdos_agent,pdos_next_auth,pdos_next_dispatch', 'ALTER TABLE public."automation_service_grants" ENABLE ROW LEVEL SECURITY', 'ALTER TABLE public."automation_service_grants" FORCE ROW LEVEL SECURITY', 'CREATE POLICY owner_internal ON public."automation_service_grants" TO pdos_next_owner USING(true) WITH CHECK(true)', 'CREATE POLICY automation_service_read ON public."automation_service_grants" FOR SELECT TO pdos_next_app,pdos_agent USING(public.category_access(tenant_id,category_id,false) AND owner_id=public.scope_requester())', 'CREATE POLICY automation_service_insert ON public."automation_service_grants" FOR INSERT TO pdos_next_app WITH CHECK(public.category_access(tenant_id,category_id,false) AND owner_id=public.scope_requester() AND owner_id=public.scope_actor() AND public.category_access(tenant_id,category_id,true) AND EXISTS(SELECT 1 FROM public.principals h WHERE h.tenant_id=automation_service_grants.tenant_id AND h.id=automation_service_grants.owner_id AND h.active AND h.kind=\'human\'))', 'REVOKE ALL ON public."automation_service_grants" FROM PUBLIC,pdos_next_app,pdos_agent,pdos_next_auth,pdos_next_dispatch', 'GRANT SELECT ON public."automation_service_grants" TO pdos_next_app,pdos_agent', 'GRANT INSERT ON public."automation_service_grants" TO pdos_next_app', 'ALTER TABLE public."automation_causal_chains" ENABLE ROW LEVEL SECURITY', 'ALTER TABLE public."automation_causal_chains" FORCE ROW LEVEL SECURITY', 'CREATE POLICY owner_internal ON public."automation_causal_chains" TO pdos_next_owner USING(true) WITH CHECK(true)', 'CREATE POLICY automation_service_read ON public."automation_causal_chains" FOR SELECT TO pdos_next_app,pdos_agent USING(public.category_access(tenant_id,category_id,false) AND owner_id=public.scope_requester())', 'CREATE POLICY automation_service_insert ON public."automation_causal_chains" FOR INSERT TO pdos_next_app WITH CHECK(public.category_access(tenant_id,category_id,false) AND owner_id=public.scope_requester() AND EXISTS(SELECT 1 FROM public.automation_service_grants g WHERE g.tenant_id=automation_causal_chains.tenant_id AND g.id=automation_causal_chains.root_grant_id AND g.owner_id=automation_causal_chains.owner_id AND g.category_id=automation_causal_chains.category_id AND g.writer_id=public.scope_actor()))', 'REVOKE ALL ON public."automation_causal_chains" FROM PUBLIC,pdos_next_app,pdos_agent,pdos_next_auth,pdos_next_dispatch', 'GRANT SELECT ON public."automation_causal_chains" TO pdos_next_app,pdos_agent', 'GRANT INSERT ON public."automation_causal_chains" TO pdos_next_app', 'ALTER TABLE public."automation_service_attempts" ENABLE ROW LEVEL SECURITY', 'ALTER TABLE public."automation_service_attempts" FORCE ROW LEVEL SECURITY', 'CREATE POLICY owner_internal ON public."automation_service_attempts" TO pdos_next_owner USING(true) WITH CHECK(true)', 'CREATE POLICY automation_service_read ON public."automation_service_attempts" FOR SELECT TO pdos_next_app,pdos_agent USING(public.category_access(tenant_id,category_id,false) AND owner_id=public.scope_requester())', 'CREATE POLICY automation_service_insert ON public."automation_service_attempts" FOR INSERT TO pdos_next_app WITH CHECK(public.category_access(tenant_id,category_id,false) AND owner_id=public.scope_requester() AND writer_id=public.scope_actor() AND EXISTS(SELECT 1 FROM public.principals a WHERE a.tenant_id=automation_service_attempts.tenant_id AND a.id=automation_service_attempts.writer_id AND a.active AND a.kind=\'agent\'))', 'REVOKE ALL ON public."automation_service_attempts" FROM PUBLIC,pdos_next_app,pdos_agent,pdos_next_auth,pdos_next_dispatch', 'GRANT SELECT ON public."automation_service_attempts" TO pdos_next_app,pdos_agent', 'GRANT INSERT ON public."automation_service_attempts" TO pdos_next_app', 'CREATE POLICY automation_service_close ON public."automation_service_attempts" FOR UPDATE TO pdos_next_app USING(public.category_access(tenant_id,category_id,false) AND owner_id=public.scope_requester() AND writer_id=public.scope_actor() AND EXISTS(SELECT 1 FROM public.principals a WHERE a.tenant_id=automation_service_attempts.tenant_id AND a.id=automation_service_attempts.writer_id AND a.active AND a.kind=\'agent\')) WITH CHECK(public.category_access(tenant_id,category_id,false) AND owner_id=public.scope_requester() AND writer_id=public.scope_actor() AND EXISTS(SELECT 1 FROM public.principals a WHERE a.tenant_id=automation_service_attempts.tenant_id AND a.id=automation_service_attempts.writer_id AND a.active AND a.kind=\'agent\'))', 'GRANT UPDATE(state,error_code,run_id,admitted_at) ON public."automation_service_attempts" TO pdos_next_app', 'CREATE TRIGGER automation_service_category_immutable BEFORE UPDATE ON public.automation_service_grants FOR EACH ROW EXECUTE FUNCTION public.protect_category_binding()', 'CREATE TRIGGER lifecycle_reference BEFORE INSERT OR UPDATE OR DELETE ON public.automation_service_grants FOR EACH ROW EXECUTE FUNCTION public.lifecycle_reference_gate()', 'CREATE TRIGGER category_lifecycle_clock AFTER INSERT OR UPDATE OR DELETE ON public.automation_service_grants FOR EACH ROW EXECUTE FUNCTION public.category_lifecycle_clock()', 'CREATE CONSTRAINT TRIGGER automation_service_atom AFTER INSERT ON public.automation_service_grants DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.require_automation_service_grant()', 'CREATE TRIGGER automation_service_immutable BEFORE UPDATE OR DELETE ON public.automation_service_grants FOR EACH ROW EXECUTE FUNCTION public.reject_automation_service_mutation()', 'CREATE TRIGGER automation_service_category_immutable BEFORE UPDATE ON public.automation_causal_chains FOR EACH ROW EXECUTE FUNCTION public.protect_category_binding()', 'CREATE TRIGGER lifecycle_reference BEFORE INSERT OR UPDATE OR DELETE ON public.automation_causal_chains FOR EACH ROW EXECUTE FUNCTION public.lifecycle_reference_gate()', 'CREATE TRIGGER category_lifecycle_clock AFTER INSERT OR UPDATE OR DELETE ON public.automation_causal_chains FOR EACH ROW EXECUTE FUNCTION public.category_lifecycle_clock()', 'CREATE CONSTRAINT TRIGGER automation_service_atom AFTER INSERT ON public.automation_causal_chains DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.require_automation_causal_chain()', 'CREATE TRIGGER automation_service_immutable BEFORE UPDATE OR DELETE ON public.automation_causal_chains FOR EACH ROW EXECUTE FUNCTION public.reject_automation_service_mutation()', 'CREATE TRIGGER automation_service_category_immutable BEFORE UPDATE ON public.automation_service_attempts FOR EACH ROW EXECUTE FUNCTION public.protect_category_binding()', 'CREATE TRIGGER lifecycle_reference BEFORE INSERT OR UPDATE OR DELETE ON public.automation_service_attempts FOR EACH ROW EXECUTE FUNCTION public.lifecycle_reference_gate()', 'CREATE TRIGGER category_lifecycle_clock AFTER INSERT OR UPDATE OR DELETE ON public.automation_service_attempts FOR EACH ROW EXECUTE FUNCTION public.category_lifecycle_clock()', 'CREATE CONSTRAINT TRIGGER automation_service_atom AFTER INSERT OR UPDATE ON public.automation_service_attempts DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.require_automation_service_attempt()', 'CREATE TRIGGER automation_service_attempt_guard BEFORE INSERT OR UPDATE OR DELETE ON public.automation_service_attempts FOR EACH ROW EXECUTE FUNCTION public.protect_automation_service_attempt()', "CREATE OR REPLACE FUNCTION public.assert_automation_version(t uuid, target uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\n\nDECLARE v public.automation_rule_versions; cur public.automation_rule_currents; envelope jsonb; vx xid; rx xid; cx xid;\nBEGIN\n SELECT * INTO STRICT v FROM public.automation_rule_versions WHERE tenant_id=t AND id=target;\n SELECT * INTO STRICT cur FROM public.automation_rule_currents WHERE tenant_id=t AND rule_id=v.rule_id;\n SELECT xmin INTO vx FROM public.automation_rule_versions WHERE tenant_id=t AND id=v.id;\n SELECT xmin INTO rx FROM public.action_receipts WHERE tenant_id=t AND id=v.receipt_id;\n SELECT xmin INTO cx FROM public.automation_rule_currents WHERE tenant_id=t AND id=cur.id;\n PERFORM public.assert_automation_members(t,target);\n envelope=v.command->'envelope';\n IF vx IS DISTINCT FROM rx OR vx IS DISTINCT FROM cx\n  OR ROW(cur.category_id,cur.owner_id,cur.version_id,cur.revision) IS DISTINCT FROM ROW(v.category_id,v.owner_id,v.id,v.revision)\n  OR v.owner_id IS DISTINCT FROM public.scope_actor() OR v.owner_id IS DISTINCT FROM public.scope_requester()\n  OR NOT public.category_access(t,v.category_id,true)\n  OR NOT EXISTS(SELECT 1 FROM public.principals p WHERE p.tenant_id=t AND p.id=v.owner_id AND p.active AND p.kind='human')\n  OR NOT EXISTS(SELECT 1 FROM public.categories c WHERE c.tenant_id=t AND c.id=v.category_id AND c.revision::text=envelope->>'expected_revision')\n  OR envelope->>'category_id' IS DISTINCT FROM v.category_id::text OR envelope->'product_id' IS DISTINCT FROM 'null'::jsonb\n  OR envelope->>'operation' IS DISTINCT FROM v.operation OR envelope->>'command_id' IS DISTINCT FROM v.command_id::text\n  OR envelope->'source_read_set' IS DISTINCT FROM '[]'::jsonb\n  OR (v.action='draft' AND envelope->'payload'->'spec' IS DISTINCT FROM v.spec)\n  OR v.command->'review'->>'operation' IS DISTINCT FROM v.operation\n  OR v.command->'review'->'declaration' IS DISTINCT FROM envelope->'payload'\n  OR v.command->'review'->'after' IS DISTINCT FROM jsonb_build_object('rule_id',v.rule_id,'revision',v.revision,'action',v.action,'state',v.state,'spec',v.spec)\n  OR v.command->'review'->>'effect' IS DISTINCT FROM (CASE WHEN v.spec->>'trigger_kind'='manual' THEN '规则仅供本人手动触发只读工作；暂停只阻止新受理。' ELSE '按固定服务授权自动触发小Pai只读工作；暂停只阻止新受理。' END)\n  OR NOT COALESCE(v.spec->>'trigger_kind' IN ('manual','schedule','domain_event','relative_milestone'),false) OR (v.spec->>'trigger_kind'<>'manual' AND (jsonb_typeof(v.spec->'trigger_config') IS DISTINCT FROM 'object' OR v.spec->'external_sources_enabled' IS DISTINCT FROM 'false'::jsonb OR (v.spec->>'max_cascade_depth')::integer<0)) OR v.spec->'allow_network' IS DISTINCT FROM 'false'::jsonb\n  OR v.spec->'mcp_tools' IS DISTINCT FROM '[]'::jsonb OR v.spec->'cross_object_write' IS DISTINCT FROM 'false'::jsonb\n  OR EXISTS(SELECT 1 FROM public.audit_entries a WHERE a.tenant_id=t AND a.receipt_id=v.receipt_id AND a.xmin IS DISTINCT FROM vx)\n  OR EXISTS(SELECT 1 FROM public.outbox_events e WHERE e.tenant_id=t AND e.receipt_id=v.receipt_id AND e.xmin IS DISTINCT FROM vx)\n  OR NOT EXISTS(SELECT 1 FROM public.request_keys k WHERE k.tenant_id=t AND k.receipt_id=v.receipt_id AND k.actor_id=v.actor_id AND k.digest=v.request_digest AND k.xmin=vx AND encode(sha256(convert_to(k.key,'UTF8')),'hex')=v.command->>'original_key_sha256') THEN\n  RAISE EXCEPTION 'Automation version requires current human and one actual common transaction' USING ERRCODE='23514'; END IF;\n IF v.action='activate' AND v.spec->>'trigger_kind'<>'manual' THEN\n  IF (SELECT count(*) FROM public.automation_service_grants g WHERE g.tenant_id=t AND g.published_version_id=v.id)<>1\n   OR NOT EXISTS(SELECT 1 FROM public.automation_service_grants g WHERE g.tenant_id=t AND g.published_version_id=v.id\n    AND v.command->'review'->'service_authorization'=jsonb_build_object('service_principal_id',g.writer_id,'delegator_id',v.owner_id,\n     'category_id',v.category_id,'product_id',v.spec->'product_id','purpose',v.spec->>'purpose','budget',v.spec->'budget','expires_at',v.spec#>'{trigger_config,expires_at}')) THEN\n   RAISE EXCEPTION 'Automatic activation requires its exact server bound named service grant' USING ERRCODE='23514'; END IF;\n END IF;\n IF envelope->'payload'->>'restored_from' IS NOT NULL AND NOT EXISTS(\n  SELECT 1 FROM public.automation_rule_versions old WHERE old.tenant_id=t AND old.category_id=v.category_id\n   AND old.owner_id=v.owner_id AND old.rule_id=v.rule_id AND old.id::text=envelope->'payload'->>'restored_from'\n   AND old.spec=v.spec AND old.spec_sha256=v.spec_sha256 AND old.revision<v.revision) THEN\n  RAISE EXCEPTION 'Automation rollback copies an actual prior version into new draft' USING ERRCODE='23514'; END IF;\n IF v.confirmation_id IS NOT NULL THEN\n  SELECT xmin INTO cx FROM public.confirmations WHERE tenant_id=t AND id=v.confirmation_id;\n  IF cx IS DISTINCT FROM vx THEN RAISE EXCEPTION 'Automation confirmation must consume in its fact transaction' USING ERRCODE='23514'; END IF;\n END IF;\nEND;\n$function$\n", "CREATE OR REPLACE FUNCTION public.require_automation_current()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\n\nDECLARE cur public.automation_rule_currents; v public.automation_rule_versions; count_actual bigint; last_actual timestamptz; cx xid; vx xid;\nBEGIN\n SELECT * INTO STRICT cur FROM public.automation_rule_currents WHERE tenant_id=NEW.tenant_id AND id=NEW.id;\n SELECT * INTO STRICT v FROM public.automation_rule_versions WHERE tenant_id=cur.tenant_id AND id=cur.version_id;\n IF ROW(cur.category_id,cur.owner_id,cur.rule_id,cur.revision) IS DISTINCT FROM ROW(v.category_id,v.owner_id,v.rule_id,v.revision)\n  OR (cur.draft_version_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.automation_rule_versions d WHERE d.tenant_id=cur.tenant_id AND d.id=cur.draft_version_id AND d.action='draft'))\n  OR (cur.published_version_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.automation_rule_versions p WHERE p.tenant_id=cur.tenant_id AND p.id=cur.published_version_id AND p.action='activate'))\n  OR (cur.state IN ('active','paused') AND cur.published_version_id IS NULL) THEN\n  RAISE EXCEPTION 'Automation Current requires exact actual version pointers' USING ERRCODE='23514'; END IF;\n IF TG_OP='INSERT' OR NEW.version_id IS DISTINCT FROM OLD.version_id THEN\n  SELECT xmin INTO cx FROM public.automation_rule_currents WHERE tenant_id=cur.tenant_id AND id=cur.id;\n  SELECT xmin INTO vx FROM public.automation_rule_versions WHERE tenant_id=v.tenant_id AND id=v.id;\n  IF cx IS DISTINCT FROM vx THEN RAISE EXCEPTION 'Automation Current and appended version share transaction' USING ERRCODE='23514'; END IF;\n END IF;\n SELECT count(*),max(admitted_at) INTO count_actual,last_actual FROM (SELECT created_at AS admitted_at,id FROM public.automation_trigger_occurrences WHERE tenant_id=cur.tenant_id AND rule_id=cur.rule_id UNION ALL SELECT admitted_at,id FROM public.automation_service_attempts WHERE tenant_id=cur.tenant_id AND rule_id=cur.rule_id AND state='admitted') admissions;\n IF cur.admitted_count IS DISTINCT FROM count_actual OR cur.last_admitted_at IS DISTINCT FROM last_actual THEN\n  RAISE EXCEPTION 'Automation counter requires actual occurrence history' USING ERRCODE='23514'; END IF;\n RETURN NULL;\nEND;\n$function$\n", "CREATE OR REPLACE FUNCTION public.assert_automation_occurrence(t uuid, target uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\n\nDECLARE o public.automation_trigger_occurrences; v public.automation_rule_versions; cur public.automation_rule_currents; r public.agent_runs; b public.agent_validation_budgets; ox xid; rx xid; cx xid; count_actual bigint; last_actual timestamptz; previous_at timestamptz;\nBEGIN\n SELECT * INTO STRICT o FROM public.automation_trigger_occurrences WHERE tenant_id=t AND id=target;\n SELECT * INTO STRICT v FROM public.automation_rule_versions WHERE tenant_id=t AND id=o.published_version_id;\n SELECT * INTO STRICT cur FROM public.automation_rule_currents WHERE tenant_id=t AND rule_id=o.rule_id;\n SELECT * INTO STRICT r FROM public.agent_runs WHERE tenant_id=t AND id=o.run_id;\n SELECT * INTO STRICT b FROM public.agent_validation_budgets WHERE tenant_id=t AND id=r.validation_budget_id;\n SELECT xmin INTO ox FROM public.automation_trigger_occurrences WHERE tenant_id=t AND id=o.id;\n SELECT xmin INTO rx FROM public.agent_runs WHERE tenant_id=t AND id=r.id;\n SELECT xmin INTO cx FROM public.automation_rule_currents WHERE tenant_id=t AND id=cur.id;\n SELECT count(*),max(admitted_at) INTO count_actual,last_actual FROM (SELECT created_at AS admitted_at,id FROM public.automation_trigger_occurrences WHERE tenant_id=t AND rule_id=o.rule_id UNION ALL SELECT admitted_at,id FROM public.automation_service_attempts WHERE tenant_id=t AND rule_id=o.rule_id AND state='admitted') admissions;\n SELECT max(admitted_at) INTO previous_at FROM (SELECT created_at AS admitted_at,id FROM public.automation_trigger_occurrences WHERE tenant_id=t AND rule_id=o.rule_id UNION ALL SELECT admitted_at,id FROM public.automation_service_attempts WHERE tenant_id=t AND rule_id=o.rule_id AND state='admitted') admissions WHERE id<>o.id;\n IF ROW(v.category_id,v.owner_id,v.rule_id) IS DISTINCT FROM ROW(o.category_id,o.owner_id,o.rule_id)\n  OR ROW(cur.category_id,cur.owner_id,cur.published_version_id,cur.state) IS DISTINCT FROM ROW(o.category_id,o.owner_id,o.published_version_id,'active'::varchar)\n  OR v.action<>'activate' OR v.state<>'active' OR v.spec->>'trigger_kind' IS DISTINCT FROM 'manual'\n  OR o.owner_id IS DISTINCT FROM public.scope_actor() OR o.owner_id IS DISTINCT FROM public.scope_requester()\n  OR NOT public.category_access(t,o.category_id,true)\n  OR NOT EXISTS(SELECT 1 FROM public.principals p WHERE p.tenant_id=t AND p.id=o.requester_id AND p.kind='human' AND p.active)\n  OR ROW(r.category_id,r.requester_id,r.trigger,r.goal,r.intent_key,r.intent_digest,r.validation_budget_id,r.token_limit)\n    IS DISTINCT FROM ROW(o.category_id,o.requester_id,'automation_manual'::varchar,v.spec->>'goal',('automation:'||o.intent_key)::varchar,o.request_digest,(v.spec->>'validation_budget_id')::uuid,(v.spec->>'token_limit')::integer)\n  OR r.product_id IS DISTINCT FROM (v.spec->>'product_id')::uuid OR r.proposal_id IS NOT NULL OR r.continued_from_id IS NOT NULL\n  OR r.read_sources IS DISTINCT FROM '[]'::jsonb\n  OR b.requester_id<>o.owner_id OR NOT b.active\n  OR cur.admitted_count IS DISTINCT FROM count_actual OR cur.last_admitted_at IS DISTINCT FROM last_actual\n  OR count_actual>(v.spec->>'max_runs')::integer\n  OR (previous_at IS NOT NULL AND o.created_at<previous_at+make_interval(secs=>(v.spec->>'cooldown_seconds')::integer))\n  OR o.created_at<r.created_at OR o.created_at<v.created_at\n  OR ox IS DISTINCT FROM rx OR ox IS DISTINCT FROM cx THEN\n  RAISE EXCEPTION 'Manual occurrence requires exact saved rule new human Run and counter' USING ERRCODE='23514'; END IF;\nEND;\n$function$\n", "CREATE OR REPLACE FUNCTION public.kernel_scope_failed(rid uuid)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\n      DECLARE r agent_runs; cid uuid; prior_actor text; lost boolean;\n      BEGIN\n        SELECT * INTO r FROM agent_runs WHERE id=rid\n          AND tenant_id=NULLIF(current_setting('pdos.tenant_id',true),'')::uuid\n          AND requester_id=scope_requester() AND CASE WHEN trigger='automation_service' THEN writer_id=scope_actor() ELSE requester_id=scope_actor() END\n          AND category_id IS NOT DISTINCT FROM\n            NULLIF(current_setting('pdos.category_id',true),'')::uuid FOR UPDATE;\n        IF NOT FOUND OR r.reverted_at IS NOT NULL OR r.state IN ('completed','partial','failed','cancelled') THEN RETURN false; END IF;\n        prior_actor=current_setting('pdos.actor_id',true);\n        PERFORM set_config('pdos.actor_id',r.writer_id::text,true);\n        lost=(r.trigger='automation_service' AND NOT EXISTS(SELECT 1 FROM public.automation_service_attempts a\n          JOIN public.automation_service_grants g ON g.tenant_id=a.tenant_id AND g.id=a.service_grant_id\n          WHERE a.tenant_id=r.tenant_id AND a.run_id=r.id AND a.state='admitted'\n            AND a.owner_id=r.requester_id AND a.writer_id=r.writer_id AND (g.expires_at IS NULL OR statement_timestamp()<g.expires_at)))\n          OR NOT EXISTS(SELECT 1 FROM principals p WHERE p.tenant_id=r.tenant_id\n            AND p.id=r.writer_id AND p.kind='agent' AND p.active)\n          OR NOT EXISTS(SELECT 1 FROM principals p WHERE p.tenant_id=r.tenant_id\n            AND p.id=r.requester_id AND p.kind='human' AND p.active)\n          OR (r.category_id IS NOT NULL AND NOT category_access(r.tenant_id,r.category_id))\n          OR NOT kernel_read_set_visible(r.tenant_id,r.category_id,r.read_sources)\n          OR (r.validation_budget_id IS NOT NULL AND NOT EXISTS(\n            SELECT 1 FROM agent_validation_budgets b WHERE b.id=r.validation_budget_id\n              AND b.tenant_id=r.tenant_id AND b.active))\n          OR (r.product_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM products p\n            WHERE p.id=r.product_id AND p.tenant_id=r.tenant_id AND p.category_id=r.category_id\n              AND (p.visibility='category' OR p.owner_id=r.requester_id OR EXISTS(\n                SELECT 1 FROM object_audiences a WHERE a.tenant_id=p.tenant_id\n                  AND a.category_id=p.category_id AND a.object_type='products'\n                  AND a.subject_id=p.id AND a.owner_id=p.owner_id AND a.principal_id=r.requester_id))));\n        IF NOT COALESCE(lost,true) THEN\n          PERFORM set_config('pdos.actor_id',prior_actor,true); RETURN false;\n        END IF;\n        FOR cid IN SELECT id FROM agent_tool_calls WHERE tenant_id=r.tenant_id\n            AND run_id=r.id AND state='started' ORDER BY id LOOP\n          PERFORM kernel_release_call(r.id,cid,'FORBIDDEN_SCOPE',true,0,NULL);\n        END LOOP;\n        PERFORM set_config('pdos.actor_id',prior_actor,true);\n        UPDATE agent_runs SET state='failed',error_code='FORBIDDEN_SCOPE',result=NULL WHERE id=r.id;\n        RETURN true;\n      END $function$\n", "CREATE FUNCTION public.automation_active_grants(t uuid) RETURNS TABLE(tenant_id uuid,category_id uuid,owner_id uuid,writer_id uuid,grant_id uuid)\nLANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $automation_service$\n\n SELECT g.tenant_id,g.category_id,g.owner_id,g.writer_id,g.id FROM public.automation_service_grants g\n JOIN public.automation_rule_currents cur ON cur.tenant_id=g.tenant_id AND cur.rule_id=g.rule_id\n WHERE g.tenant_id=t AND t=nullif(current_setting('pdos.tenant_id',true),'')::uuid\n  AND cur.state='active' AND cur.published_version_id=g.published_version_id\n  AND NOT EXISTS(SELECT 1 FROM public.automation_service_attempts stopped WHERE stopped.tenant_id=t\n   AND stopped.service_grant_id=g.id AND stopped.origin->>'kind'='lifecycle' AND stopped.state='suppressed')\n ORDER BY g.created_at,g.id;\n$automation_service$", "CREATE FUNCTION public.automation_event_targets(t uuid,event_ref uuid,lease_ref uuid) RETURNS TABLE(tenant_id uuid,category_id uuid,owner_id uuid,writer_id uuid,grant_id uuid)\nLANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $automation_service$\n\n SELECT g.tenant_id,g.category_id,g.owner_id,g.writer_id,g.id FROM public.automation_service_grants g\n JOIN public.automation_rule_currents cur ON cur.tenant_id=g.tenant_id AND cur.rule_id=g.rule_id\n JOIN public.automation_rule_versions v ON v.tenant_id=g.tenant_id AND v.id=g.published_version_id\n JOIN public.outbox_events e ON e.tenant_id=g.tenant_id AND e.category_id=g.category_id\n JOIN public.action_receipts receipt ON receipt.tenant_id=e.tenant_id AND receipt.id=e.receipt_id\n WHERE g.tenant_id=t AND t=nullif(current_setting('pdos.tenant_id',true),'')::uuid\n  AND e.id=event_ref AND e.lease_id=lease_ref AND e.lease_until>statement_timestamp() AND e.delivered_at IS NULL\n  AND e.schema_version=1 AND cur.state='active' AND cur.published_version_id=g.published_version_id\n  AND v.spec->>'trigger_kind'='domain_event' AND (v.spec#>'{trigger_config,event_types}') ? e.type\n  AND ((v.spec#>>'{trigger_config,subject_id}') IS NULL OR (v.spec#>>'{trigger_config,subject_id}')::uuid=e.subject_id)\n  AND (v.spec->>'product_id' IS NULL OR (v.spec->>'product_id')::uuid=receipt.product_id)\n  AND NOT EXISTS(SELECT 1 FROM public.automation_service_attempts stopped WHERE stopped.tenant_id=t\n    AND stopped.service_grant_id=g.id AND stopped.origin->>'kind'='lifecycle' AND stopped.state='suppressed')\n ORDER BY g.id;\n$automation_service$", "CREATE FUNCTION public.kernel_pending_run_references(t uuid,page_limit integer) RETURNS TABLE(tenant_id uuid,category_id uuid,actor_id uuid,requester_id uuid,run_id uuid)\nLANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $automation_service$\n\n SELECT r.tenant_id,r.category_id,CASE WHEN r.trigger='automation_service' THEN r.writer_id ELSE r.requester_id END,\n  r.requester_id,r.id FROM public.agent_runs r\n WHERE r.tenant_id=t AND t=nullif(current_setting('pdos.tenant_id',true),'')::uuid\n  AND r.state='queued' AND r.reverted_at IS NULL\n  AND (r.trigger<>'automation_service' OR EXISTS(SELECT 1 FROM public.automation_service_attempts a\n   JOIN public.automation_service_grants g ON g.tenant_id=a.tenant_id AND g.id=a.service_grant_id\n   WHERE a.tenant_id=t AND a.run_id=r.id AND a.state='admitted' AND a.owner_id=r.requester_id AND a.writer_id=r.writer_id))\n ORDER BY r.created_at,r.id LIMIT LEAST(GREATEST(page_limit,1),200);\n$automation_service$", "CREATE FUNCTION public.automation_event_parent(grant_ref uuid,event_ref uuid) RETURNS TABLE(chain_id uuid,depth integer,run_id uuid,rule_id uuid)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $automation_service$\n\nDECLARE g public.automation_service_grants; e public.outbox_events;\nBEGIN\n SELECT * INTO STRICT g FROM public.automation_service_grants WHERE id=grant_ref AND tenant_id=nullif(current_setting('pdos.tenant_id',true),'')::uuid;\n IF NOT public.automation_service_identity(g.tenant_id,g.owner_id,g.writer_id)\n  OR NOT public.category_access(g.tenant_id,g.category_id,false) THEN RAISE EXCEPTION 'Service event scope invalid'; END IF;\n SELECT * INTO STRICT e FROM public.outbox_events WHERE id=event_ref AND tenant_id=g.tenant_id AND category_id=g.category_id;\n -- Metadata only, and only after the source receipt is visible to the caller.\n IF NOT EXISTS(SELECT 1 FROM public.action_receipts receipt WHERE receipt.tenant_id=g.tenant_id AND receipt.id=e.receipt_id\n  AND (receipt.visibility='category' OR receipt.requester_id=g.owner_id OR EXISTS(\n   SELECT 1 FROM public.object_audiences audience WHERE audience.tenant_id=g.tenant_id AND audience.category_id=g.category_id\n    AND audience.object_type='action_receipts' AND audience.subject_id=receipt.id AND audience.owner_id=receipt.requester_id AND audience.principal_id=g.owner_id))\n  AND (receipt.product_id IS NULL OR EXISTS(SELECT 1 FROM public.products product WHERE product.tenant_id=g.tenant_id\n   AND product.id=receipt.product_id AND product.category_id=g.category_id AND (product.visibility='category' OR product.owner_id=g.owner_id OR EXISTS(\n    SELECT 1 FROM public.object_audiences audience WHERE audience.tenant_id=g.tenant_id AND audience.category_id=g.category_id\n    AND audience.object_type='products' AND audience.subject_id=product.id AND audience.owner_id=product.owner_id AND audience.principal_id=g.owner_id)))))\n THEN RAISE EXCEPTION 'Service event receipt unavailable'; END IF;\n RETURN QUERY SELECT a.chain_id,a.depth,a.run_id,a.rule_id FROM public.action_receipts r\n JOIN public.automation_service_attempts a ON a.tenant_id=r.tenant_id AND a.run_id=r.agent_run_id AND a.state='admitted'\n WHERE r.tenant_id=g.tenant_id AND r.id=e.receipt_id;\nEND;\n$automation_service$", "CREATE FUNCTION public.automation_chain_reserve(run_ref uuid,extra_cost bigint,extra_in bigint,extra_out bigint) RETURNS boolean\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $automation_service$\n\nDECLARE a public.automation_service_attempts; chain public.automation_causal_chains; used_cost numeric; used_in numeric; used_out numeric; used_calls bigint;\nBEGIN\n SELECT * INTO STRICT a FROM public.automation_service_attempts WHERE run_id=run_ref\n  AND tenant_id=nullif(current_setting('pdos.tenant_id',true),'')::uuid AND state='admitted';\n IF NOT public.automation_service_identity(a.tenant_id,a.owner_id,a.writer_id)\n  OR NOT public.category_access(a.tenant_id,a.category_id,false)\n  OR NOT EXISTS(SELECT 1 FROM public.agent_runs r WHERE r.tenant_id=a.tenant_id AND r.id=run_ref\n    AND r.requester_id=a.owner_id AND r.writer_id=a.writer_id AND r.trigger='automation_service')\n  OR extra_cost<0 OR extra_in<0 OR extra_out<0 THEN RAISE EXCEPTION 'Service chain reservation requires actual Run identity'; END IF;\n PERFORM pg_advisory_xact_lock(hashtextextended('automation-chain:'||a.chain_id,0));\n SELECT * INTO STRICT chain FROM public.automation_causal_chains WHERE tenant_id=a.tenant_id AND id=a.chain_id;\n SELECT coalesce(sum(CASE WHEN c.cost_state='reserved' THEN c.cost_reserved_micro_usd ELSE c.cost_charged_micro_usd END),0),\n  coalesce(sum(CASE WHEN c.cost_state='reserved' THEN c.input_token_reservation ELSE c.actual_input_tokens END),0),\n  coalesce(sum(CASE WHEN c.cost_state='reserved' THEN c.output_token_reservation ELSE c.actual_output_tokens END),0),count(*)\n INTO used_cost,used_in,used_out,used_calls FROM public.agent_tool_calls c\n JOIN public.automation_service_attempts child ON child.tenant_id=c.tenant_id AND child.run_id=c.run_id\n WHERE child.tenant_id=a.tenant_id AND child.chain_id=a.chain_id AND child.state='admitted' AND c.cost_state<>'unmetered';\n RETURN used_cost+extra_cost<=(chain.budget->>'limit_micro_usd')::bigint\n  AND used_in+extra_in<=(chain.budget->>'input_token_limit')::bigint\n  AND used_out+extra_out<=(chain.budget->>'output_token_limit')::bigint\n  AND used_calls+1<=(chain.budget->>'call_limit')::bigint;\nEND;\n$automation_service$", 'REVOKE ALL ON FUNCTION public.automation_active_grants(uuid) FROM PUBLIC,pdos_next_app,pdos_agent,pdos_next_auth,pdos_next_dispatch', 'REVOKE ALL ON FUNCTION public.automation_event_targets(uuid,uuid,uuid) FROM PUBLIC,pdos_next_app,pdos_agent,pdos_next_auth,pdos_next_dispatch', 'REVOKE ALL ON FUNCTION public.kernel_pending_run_references(uuid,integer) FROM PUBLIC,pdos_next_app,pdos_agent,pdos_next_auth,pdos_next_dispatch', 'REVOKE ALL ON FUNCTION public.automation_event_parent(uuid,uuid) FROM PUBLIC,pdos_next_app,pdos_agent,pdos_next_auth,pdos_next_dispatch', 'REVOKE ALL ON FUNCTION public.automation_chain_reserve(uuid,bigint,bigint,bigint) FROM PUBLIC,pdos_next_app,pdos_agent,pdos_next_auth,pdos_next_dispatch', 'GRANT EXECUTE ON FUNCTION public.automation_active_grants(uuid) TO pdos_next_dispatch', 'GRANT EXECUTE ON FUNCTION public.automation_event_targets(uuid,uuid,uuid) TO pdos_next_dispatch', 'GRANT EXECUTE ON FUNCTION public.kernel_pending_run_references(uuid,integer) TO pdos_next_dispatch', 'GRANT EXECUTE ON FUNCTION public.automation_event_parent(uuid,uuid) TO pdos_next_app,pdos_agent', 'GRANT EXECUTE ON FUNCTION public.automation_chain_reserve(uuid,bigint,bigint,bigint) TO pdos_next_app,pdos_agent', "CREATE FUNCTION public.automation_service_stop(grant_id uuid,stop_reason text) RETURNS uuid\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $automation_commands$\n\nDECLARE t uuid=nullif(current_setting('pdos.tenant_id',true),'')::uuid;\n g public.automation_service_grants; v public.automation_rule_versions; prior public.automation_service_attempts;\n chain_id uuid; attempt_id uuid; point timestamptz; origin_value jsonb; fingerprint text;\nBEGIN\n IF stop_reason IS NULL OR stop_reason NOT IN ('GOAL_REACHED','SCOPE_INVALID','EXPIRED','SUPERSEDED','MAX_RUNS','MODEL_BUDGET_EXHAUSTED') THEN\n  RAISE EXCEPTION 'Unregistered service stop reason' USING ERRCODE='23514'; END IF;\n SELECT * INTO STRICT g FROM public.automation_service_grants WHERE tenant_id=t AND id=grant_id;\n IF NOT COALESCE(public.automation_service_identity(t,g.owner_id,g.writer_id),false)\n  OR g.category_id IS DISTINCT FROM nullif(current_setting('pdos.category_id',true),'')::uuid THEN\n  RAISE EXCEPTION 'Stop requires actual stored service identity' USING ERRCODE='42501'; END IF;\n PERFORM 1 FROM public.categories WHERE tenant_id=t AND id=g.category_id FOR UPDATE;\n PERFORM pg_advisory_xact_lock(hashtextextended('automation-service-stop:'||t::text||':'||g.id::text,0));\n SELECT * INTO prior FROM public.automation_service_attempts WHERE tenant_id=t AND service_grant_id=g.id AND trigger_key='lifecycle:stop';\n IF FOUND THEN\n  IF prior.origin->>'kind' IS DISTINCT FROM 'lifecycle' OR prior.state<>'suppressed'\n   OR prior.error_code NOT IN ('GOAL_REACHED','SCOPE_INVALID','EXPIRED','SUPERSEDED','MAX_RUNS','MODEL_BUDGET_EXHAUSTED') OR prior.run_id IS NOT NULL OR prior.admitted_at IS NOT NULL THEN\n   RAISE EXCEPTION 'Original service stop record is inconsistent' USING ERRCODE='23514'; END IF;\n  RETURN prior.id;\n END IF;\n SELECT * INTO STRICT v FROM public.automation_rule_versions WHERE tenant_id=t AND id=g.published_version_id;\n point=clock_timestamp(); chain_id=gen_random_uuid(); attempt_id=gen_random_uuid();\n origin_value=jsonb_build_object('kind','lifecycle','reason',stop_reason,'grant_id',g.id,'published_version_id',v.id);\n fingerprint=encode(sha256(convert_to(g.id::text||':lifecycle:stop:'||stop_reason,'UTF8')),'hex');\n INSERT INTO public.automation_causal_chains(id,tenant_id,category_id,owner_id,root_grant_id,budget,max_depth,created_at)\n  VALUES(chain_id,t,g.category_id,g.owner_id,g.id,v.spec->'budget',(v.spec->>'max_cascade_depth')::integer,point);\n INSERT INTO public.automation_service_attempts(id,tenant_id,category_id,owner_id,writer_id,rule_id,published_version_id,service_grant_id,chain_id,parent_run_id,depth,trigger_kind,trigger_key,origin,request_digest,state,error_code,run_id,admitted_at,due_at,created_at)\n  VALUES(attempt_id,t,g.category_id,g.owner_id,g.writer_id,g.rule_id,g.published_version_id,g.id,chain_id,NULL,0,v.spec->>'trigger_kind','lifecycle:stop',origin_value,fingerprint,'queued',NULL,NULL,NULL,NULL,point);\n UPDATE public.automation_service_attempts SET state='suppressed',error_code=stop_reason WHERE tenant_id=t AND id=attempt_id;\n RETURN attempt_id;\nEND;\n$automation_commands$", "CREATE FUNCTION public.assert_automation_service_run(t uuid,rid uuid) RETURNS void\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $automation_commands$\n\nDECLARE r public.agent_runs; a public.automation_service_attempts; g public.automation_service_grants;\n v public.automation_rule_versions; session public.agent_sessions;\nBEGIN\n SELECT * INTO STRICT r FROM public.agent_runs WHERE tenant_id=t AND id=rid;\n SELECT * INTO STRICT a FROM public.automation_service_attempts WHERE tenant_id=t AND run_id=r.id AND state='admitted';\n SELECT * INTO STRICT g FROM public.automation_service_grants WHERE tenant_id=t AND id=a.service_grant_id;\n SELECT * INTO STRICT v FROM public.automation_rule_versions WHERE tenant_id=t AND id=g.published_version_id;\n SELECT * INTO STRICT session FROM public.agent_sessions WHERE tenant_id=t AND id=r.session_id;\n IF (SELECT count(*) FROM public.automation_service_attempts x WHERE x.tenant_id=t AND x.run_id=r.id AND x.state='admitted')<>1\n  OR ROW(a.category_id,a.owner_id,a.writer_id,a.rule_id,a.published_version_id) IS DISTINCT FROM ROW(g.category_id,g.owner_id,g.writer_id,g.rule_id,g.published_version_id)\n  OR ROW(g.category_id,g.owner_id,g.rule_id,g.receipt_id) IS DISTINCT FROM ROW(v.category_id,v.owner_id,v.rule_id,v.receipt_id)\n  OR v.action<>'activate' OR v.state<>'active' OR v.confirmation_id IS NULL\n  OR ROW(r.category_id,r.requester_id,r.writer_id,r.trigger,r.goal,r.intent_key,r.intent_digest,r.token_limit,r.validation_budget_id)\n   IS DISTINCT FROM ROW(g.category_id,g.owner_id,g.writer_id,'automation_service'::varchar,v.spec->>'goal',('automation-service:'||a.id)::varchar,a.request_digest,(v.spec->>'token_limit')::integer,(v.spec->>'validation_budget_id')::uuid)\n  OR r.product_id IS DISTINCT FROM (v.spec->>'product_id')::uuid OR r.proposal_id IS NOT NULL OR r.continued_from_id IS NOT NULL\n  OR ROW(session.category_id,session.product_id,session.proposal_id,session.owner_id) IS DISTINCT FROM ROW(r.category_id,r.product_id,NULL::uuid,r.requester_id)\n  OR a.admitted_at IS NULL OR r.created_at>a.admitted_at THEN\n  RAISE EXCEPTION 'Service Run requires one actual admitted attempt and original T1 grant' USING ERRCODE='23514'; END IF;\nEND;\n$automation_commands$", 'CREATE FUNCTION public.automation_service_start(attempt_id uuid) RETURNS uuid\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $automation_commands$\n\nDECLARE t uuid=nullif(current_setting(\'pdos.tenant_id\',true),\'\')::uuid;\n a public.automation_service_attempts; g public.automation_service_grants; v public.automation_rule_versions;\n chain public.automation_causal_chains; cur public.automation_rule_currents; wallet public.agent_validation_budgets;\n product public.products; point timestamptz; reason text; private_value boolean=false;\n session_id uuid; new_run_id uuid; authority_count integer;\n rule_cost numeric; rule_input numeric; rule_output numeric; rule_calls bigint;\n chain_cost numeric; chain_input numeric; chain_output numeric; chain_calls bigint;\nBEGIN\n SELECT * INTO STRICT a FROM public.automation_service_attempts WHERE tenant_id=t AND id=attempt_id;\n SELECT * INTO STRICT g FROM public.automation_service_grants WHERE tenant_id=t AND id=a.service_grant_id;\n IF NOT COALESCE(public.automation_service_identity(t,g.owner_id,g.writer_id),false)\n  OR g.category_id IS DISTINCT FROM nullif(current_setting(\'pdos.category_id\',true),\'\')::uuid\n  OR ROW(a.category_id,a.owner_id,a.writer_id,a.rule_id,a.published_version_id) IS DISTINCT FROM ROW(g.category_id,g.owner_id,g.writer_id,g.rule_id,g.published_version_id) THEN\n  RAISE EXCEPTION \'Start requires the actual fixed service identity\' USING ERRCODE=\'42501\'; END IF;\n -- The same lock order is used by lifecycle/configuration and chain reservation.\n PERFORM 1 FROM public.categories WHERE tenant_id=t AND id=g.category_id FOR UPDATE;\n PERFORM pg_advisory_xact_lock(hashtextextended(\'automation-chain:\'||a.chain_id::text,0));\n SELECT * INTO STRICT chain FROM public.automation_causal_chains WHERE tenant_id=t AND id=a.chain_id FOR UPDATE;\n PERFORM pg_advisory_xact_lock(hashtextextended(\'automation-budget:\'||t::text||\':\'||g.rule_id::text,0));\n SELECT * INTO STRICT cur FROM public.automation_rule_currents WHERE tenant_id=t AND rule_id=g.rule_id FOR UPDATE;\n SELECT * INTO STRICT a FROM public.automation_service_attempts WHERE tenant_id=t AND id=attempt_id FOR UPDATE;\n IF a.state=\'admitted\' THEN PERFORM public.assert_automation_service_run(t,a.run_id); RETURN a.run_id; ELSIF a.state=\'suppressed\' THEN RETURN NULL;\n ELSIF a.state<>\'queued\' THEN RAISE EXCEPTION \'Unknown service attempt state\' USING ERRCODE=\'23514\'; END IF;\n SELECT * INTO STRICT v FROM public.automation_rule_versions WHERE tenant_id=t AND id=g.published_version_id;\n point=clock_timestamp();\n SELECT x.error_code INTO reason FROM public.automation_service_attempts x WHERE x.tenant_id=t AND x.service_grant_id=g.id\n  AND x.origin->>\'kind\'=\'lifecycle\' AND x.state=\'suppressed\' AND x.error_code IN (\'GOAL_REACHED\',\'SCOPE_INVALID\',\'EXPIRED\',\'SUPERSEDED\',\'MAX_RUNS\',\'MODEL_BUDGET_EXHAUSTED\') ORDER BY x.created_at,x.id LIMIT 1;\n IF reason IS NULL THEN\n  IF cur.published_version_id IS DISTINCT FROM g.published_version_id OR cur.state<>\'active\' THEN reason=\'SUPERSEDED\';\n  ELSIF g.expires_at IS NOT NULL AND point>=g.expires_at THEN reason=\'EXPIRED\';\n  ELSIF NOT public.automation_service_grant_available(t,g.id,point) THEN reason=\'SCOPE_INVALID\'; END IF;\n END IF;\n IF reason IS NOT NULL THEN\n  UPDATE public.automation_service_attempts SET state=\'suppressed\',error_code=reason WHERE tenant_id=t AND id=a.id;\n  PERFORM public.automation_service_stop(g.id,reason); RETURN NULL;\n END IF;\n -- Lock current authority, then check expiry at this actual admission instant.\n PERFORM 1 FROM public.principals p WHERE p.tenant_id=t AND p.id IN (g.owner_id,g.writer_id) ORDER BY p.id FOR SHARE;\n PERFORM 1 FROM public.grants access WHERE access.tenant_id=t AND access.category_id=g.category_id AND access.principal_id IN (g.owner_id,g.writer_id) ORDER BY access.principal_id FOR SHARE;\n SELECT count(*) INTO authority_count FROM public.principals p JOIN public.grants access ON access.tenant_id=p.tenant_id AND access.principal_id=p.id\n  WHERE p.tenant_id=t AND p.id IN (g.owner_id,g.writer_id) AND p.active AND access.category_id=g.category_id\n   AND (access.expires_at IS NULL OR point<access.expires_at);\n IF authority_count<>2 THEN\n  UPDATE public.automation_service_attempts SET state=\'suppressed\',error_code=\'SCOPE_INVALID\' WHERE tenant_id=t AND id=a.id;\n  PERFORM public.automation_service_stop(g.id,\'SCOPE_INVALID\'); RETURN NULL;\n END IF;\n IF a.depth>chain.max_depth THEN\n  UPDATE public.automation_service_attempts SET state=\'suppressed\',error_code=\'CASCADE_DEPTH_EXCEEDED\' WHERE tenant_id=t AND id=a.id; RETURN NULL;\n END IF;\n IF a.parent_run_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.automation_service_attempts parent\n  WHERE parent.tenant_id=t AND parent.run_id=a.parent_run_id AND parent.state=\'admitted\' AND parent.chain_id=a.chain_id AND parent.depth+1=a.depth) THEN\n  RAISE EXCEPTION \'Service parent must be an actual admitted member of the same chain\' USING ERRCODE=\'23514\'; END IF;\n IF a.parent_run_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.automation_service_attempts parent\n  WHERE parent.tenant_id=t AND parent.run_id=a.parent_run_id AND parent.state=\'admitted\' AND parent.rule_id=g.rule_id) THEN\n  UPDATE public.automation_service_attempts SET state=\'suppressed\',error_code=\'SELF_TRIGGERED\' WHERE tenant_id=t AND id=a.id; RETURN NULL;\n END IF;\n IF cur.admitted_count>=(v.spec->>\'max_runs\')::integer THEN\n  UPDATE public.automation_service_attempts SET state=\'suppressed\',error_code=\'MAX_RUNS\' WHERE tenant_id=t AND id=a.id;\n  PERFORM public.automation_service_stop(g.id,\'MAX_RUNS\'); RETURN NULL;\n END IF;\n IF (a.due_at IS NOT NULL AND point<a.due_at)\n  OR (cur.last_admitted_at IS NOT NULL AND point<cur.last_admitted_at+make_interval(secs=>(v.spec->>\'cooldown_seconds\')::integer)) THEN RETURN NULL; END IF;\n IF v.spec->>\'product_id\' IS NOT NULL THEN\n  SELECT * INTO product FROM public.products p WHERE p.tenant_id=t AND p.category_id=g.category_id AND p.id=(v.spec->>\'product_id\')::uuid FOR SHARE;\n  IF product.id IS NULL OR NOT(product.visibility=\'category\' OR product.owner_id=g.owner_id OR EXISTS(\n   SELECT 1 FROM public.object_audiences audience WHERE audience.tenant_id=t AND audience.category_id=g.category_id\n    AND audience.object_type=\'products\' AND audience.subject_id=product.id AND audience.owner_id=product.owner_id AND audience.principal_id=g.owner_id)) THEN\n   UPDATE public.automation_service_attempts SET state=\'suppressed\',error_code=\'SCOPE_INVALID\' WHERE tenant_id=t AND id=a.id;\n   PERFORM public.automation_service_stop(g.id,\'SCOPE_INVALID\'); RETURN NULL;\n  END IF;\n  private_value=product.visibility<>\'category\';\n END IF;\n SELECT * INTO wallet FROM public.agent_validation_budgets b WHERE b.tenant_id=t AND b.id=(v.spec->>\'validation_budget_id\')::uuid FOR UPDATE;\n IF wallet.id IS NULL OR wallet.requester_id<>g.owner_id OR NOT wallet.active THEN\n  UPDATE public.automation_service_attempts SET state=\'suppressed\',error_code=\'MODEL_BUDGET_EXHAUSTED\' WHERE tenant_id=t AND id=a.id;\n  PERFORM public.automation_service_stop(g.id,\'MODEL_BUDGET_EXHAUSTED\'); RETURN NULL;\n END IF;\n SELECT coalesce(sum(CASE WHEN call.cost_state=\'reserved\' THEN call.cost_reserved_micro_usd ELSE call.cost_charged_micro_usd END),0),\n  coalesce(sum(CASE WHEN call.cost_state=\'reserved\' THEN call.input_token_reservation ELSE call.actual_input_tokens END),0),\n  coalesce(sum(CASE WHEN call.cost_state=\'reserved\' THEN call.output_token_reservation ELSE call.actual_output_tokens END),0),count(*)\n  INTO rule_cost,rule_input,rule_output,rule_calls FROM public.agent_tool_calls call JOIN (\n   SELECT service.run_id FROM public.automation_service_attempts service WHERE service.tenant_id=t AND service.rule_id=g.rule_id AND service.state=\'admitted\'\n   UNION SELECT manual.run_id FROM public.automation_trigger_occurrences manual WHERE manual.tenant_id=t AND manual.rule_id=g.rule_id\n  ) refs ON refs.run_id=call.run_id WHERE call.tenant_id=t AND call.cost_state<>\'unmetered\';\n SELECT coalesce(sum(CASE WHEN call.cost_state=\'reserved\' THEN call.cost_reserved_micro_usd ELSE call.cost_charged_micro_usd END),0),\n  coalesce(sum(CASE WHEN call.cost_state=\'reserved\' THEN call.input_token_reservation ELSE call.actual_input_tokens END),0),\n  coalesce(sum(CASE WHEN call.cost_state=\'reserved\' THEN call.output_token_reservation ELSE call.actual_output_tokens END),0),count(*)\n  INTO chain_cost,chain_input,chain_output,chain_calls FROM public.agent_tool_calls call JOIN public.automation_service_attempts member\n   ON member.tenant_id=call.tenant_id AND member.run_id=call.run_id WHERE member.tenant_id=t AND member.chain_id=chain.id AND member.state=\'admitted\' AND call.cost_state<>\'unmetered\';\n IF wallet.calls>=wallet.call_limit OR wallet.held_input_tokens::bigint+wallet.used_input_tokens>=wallet.input_token_limit\n  OR wallet.held_output_tokens::bigint+wallet.used_output_tokens>=wallet.output_token_limit\n  OR wallet.held_micro_usd::bigint+wallet.spent_micro_usd>wallet.limit_micro_usd\n  OR rule_calls>=(v.spec->\'budget\'->>\'call_limit\')::bigint OR rule_input>=(v.spec->\'budget\'->>\'input_token_limit\')::bigint\n  OR rule_output>=(v.spec->\'budget\'->>\'output_token_limit\')::bigint OR rule_cost>(v.spec->\'budget\'->>\'limit_micro_usd\')::numeric THEN\n  UPDATE public.automation_service_attempts SET state=\'suppressed\',error_code=\'MODEL_BUDGET_EXHAUSTED\' WHERE tenant_id=t AND id=a.id;\n  PERFORM public.automation_service_stop(g.id,\'MODEL_BUDGET_EXHAUSTED\'); RETURN NULL;\n END IF;\n IF chain_calls>=(chain.budget->>\'call_limit\')::bigint OR chain_input>=(chain.budget->>\'input_token_limit\')::bigint\n  OR chain_output>=(chain.budget->>\'output_token_limit\')::bigint OR chain_cost>(chain.budget->>\'limit_micro_usd\')::numeric THEN\n  UPDATE public.automation_service_attempts SET state=\'suppressed\',error_code=\'CHAIN_BUDGET_EXHAUSTED\' WHERE tenant_id=t AND id=a.id; RETURN NULL;\n END IF;\n session_id=gen_random_uuid(); new_run_id=gen_random_uuid(); point=clock_timestamp();\n -- Recheck explicit deadlines after locks and preflight; a preview is not authority.\n IF NOT public.automation_service_grant_available(t,g.id,point) OR (SELECT count(*) FROM public.principals p JOIN public.grants access\n  ON access.tenant_id=p.tenant_id AND access.principal_id=p.id WHERE p.tenant_id=t AND p.id IN (g.owner_id,g.writer_id)\n   AND p.active AND access.category_id=g.category_id AND (access.expires_at IS NULL OR point<access.expires_at))<>2 THEN\n  UPDATE public.automation_service_attempts SET state=\'suppressed\',error_code=\'SCOPE_INVALID\' WHERE tenant_id=t AND id=a.id;\n  PERFORM public.automation_service_stop(g.id,\'SCOPE_INVALID\'); RETURN NULL;\n END IF;\n INSERT INTO public.agent_sessions(id,tenant_id,created_at,category_id,product_id,proposal_id,owner_id,revision)\n  VALUES(session_id,t,point,g.category_id,(v.spec->>\'product_id\')::uuid,NULL,g.owner_id,1);\n INSERT INTO public.agent_runs(id,tenant_id,created_at,category_id,product_id,proposal_id,session_id,continued_from_id,requester_id,writer_id,trigger,goal,intent_key,intent_digest,cancel_epoch,state,private_context,data_categories,customer_identities,versions,read_sources,token_limit,validation_budget_id,held_tokens,used_tokens,result,error_code,reverted_at,reverted_by,revert_receipt_id)\n  VALUES(new_run_id,t,point,g.category_id,(v.spec->>\'product_id\')::uuid,NULL,session_id,NULL,g.owner_id,g.writer_id,\'automation_service\',v.spec->>\'goal\',\'automation-service:\'||a.id,a.request_digest,0,\'queued\',private_value,\'["internal"]\'::jsonb,\'[]\'::jsonb,\'{"checkpoint_layout":"session-run-ns/v1"}\'::jsonb,\'[]\'::jsonb,(v.spec->>\'token_limit\')::integer,wallet.id,0,0,NULL,NULL,NULL,NULL,NULL);\n INSERT INTO public.agent_run_events(id,tenant_id,created_at,run_id,sequence,body)\n  VALUES(gen_random_uuid(),t,point,new_run_id,1,\'{"type":"accepted","status":"queued"}\'::jsonb);\n UPDATE public.automation_service_attempts SET state=\'admitted\',run_id=new_run_id,admitted_at=point WHERE tenant_id=t AND id=a.id;\n UPDATE public.automation_rule_currents SET admitted_count=admitted_count+1,last_admitted_at=point WHERE tenant_id=t AND id=cur.id;\n RETURN new_run_id;\nEND;\n$automation_commands$', "CREATE FUNCTION public.require_automation_service_run() RETURNS trigger\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $automation_commands$\n\nDECLARE ax xid; rx xid;\nBEGIN\n IF NEW.trigger='automation_service' OR (TG_OP='UPDATE' AND OLD.trigger='automation_service') THEN\n  PERFORM public.assert_automation_service_run(NEW.tenant_id,NEW.id);\n  IF TG_OP='INSERT' THEN\n   IF NOT COALESCE(public.automation_service_identity(NEW.tenant_id,NEW.requester_id,NEW.writer_id),false) THEN\n    RAISE EXCEPTION 'Service Run creation keeps its actual agent actor' USING ERRCODE='42501'; END IF;\n   SELECT xmin INTO rx FROM public.agent_runs WHERE tenant_id=NEW.tenant_id AND id=NEW.id;\n   SELECT xmin INTO ax FROM public.automation_service_attempts WHERE tenant_id=NEW.tenant_id AND run_id=NEW.id AND state='admitted';\n   IF ax IS DISTINCT FROM rx THEN RAISE EXCEPTION 'Service Run and admitted attempt share one transaction' USING ERRCODE='23514'; END IF;\n  END IF;\n END IF;\n RETURN NULL;\nEND;\n$automation_commands$", 'REVOKE ALL ON FUNCTION public.automation_service_stop(uuid,text) FROM PUBLIC,pdos_next_app,pdos_agent,pdos_next_auth,pdos_next_dispatch', 'REVOKE ALL ON FUNCTION public.assert_automation_service_run(uuid,uuid) FROM PUBLIC,pdos_next_app,pdos_agent,pdos_next_auth,pdos_next_dispatch', 'REVOKE ALL ON FUNCTION public.automation_service_start(uuid) FROM PUBLIC,pdos_next_app,pdos_agent,pdos_next_auth,pdos_next_dispatch', 'REVOKE ALL ON FUNCTION public.require_automation_service_run() FROM PUBLIC,pdos_next_app,pdos_agent,pdos_next_auth,pdos_next_dispatch', 'GRANT EXECUTE ON FUNCTION public.automation_service_start(uuid) TO pdos_next_app', 'GRANT EXECUTE ON FUNCTION public.automation_service_stop(uuid,text) TO pdos_next_app', 'CREATE CONSTRAINT TRIGGER automation_service_run_atom AFTER INSERT OR UPDATE ON public.agent_runs DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.require_automation_service_run()')

